import random
random.seed(20240917)
SAMPLES = ["sampleA", "sampleB", "sampleC", "sampleD"]
N_TX, N_GENES = 1000, 250
genes = ["GENE%04d" % i for i in range(N_GENES)]
tx = ["TX%05d" % i for i in range(1, N_TX + 1)]
tx2gene = {}
for i, t in enumerate(tx):
    tx2gene[t] = genes[i] if i < N_GENES else random.choice(genes)
gene_tx = {}
for t in tx:
    gene_tx.setdefault(tx2gene[t], []).append(t)
length = {t: random.randint(400, 6000) for t in tx}
cents = {}
for s in SAMPLES:
    cents[s] = {}
    for t in tx:
        cents[s][t] = 0 if random.random() < 0.12 else random.randint(0, 900000)
for s in SAMPLES:
    for g, ts in gene_tx.items():
        if sum(cents[s][t] for t in ts) % 100 == 50:
            cents[s][ts[0]] += 1
with open("tx2gene.tsv", "w") as fh:
    fh.write("transcript_id\tgene_id\n")
    for t in tx:
        fh.write("%s\t%s\n" % (t, tx2gene[t]))
for s in SAMPLES:
    tot = sum(cents[s][t] / 100.0 / max(length[t] - 200, 50) for t in tx) or 1.0
    with open("quant_%s.sf" % s, "w") as fh:
        fh.write("Name\tLength\tEffectiveLength\tTPM\tNumReads\n")
        for t in tx:
            eff = max(length[t] - 200, 50)
            tpm = (cents[s][t] / 100.0 / eff) / tot * 1e6
            fh.write("%s\t%d\t%.3f\t%.6f\t%.2f\n" % (t, length[t], float(eff), tpm, cents[s][t] / 100.0))

