clean = 0
for u in d["users"]:
    f = {
        "drive_external_sharing": any(dom(x) not in appr for x in u["drive_external_shares"]),
        "gmail_auto_forwarding": bool(u["gmail_auto_forward_to"]) and dom(u["gmail_auto_forward_to"]) not in appr,
