import json, os, random
random.seed(1357)
os.makedirs("crds", exist_ok=True)
KINDS = ["Widget", "Cache", "Pipeline", "Cluster", "Backup", "Tenant", "Index", "Queue", "Router",
         "Certificate", "Shard", "Workflow", "Relay", "Ledger", "Probe"]
COLS = ["Age", "Status", "Phase", "Replicas", "Ready", "Version", "Endpoint"]
for i in range(150):
    kind = "%s%d" % (random.choice(KINDS), i)
    lower = kind.lower()
    names = {"kind": kind, "plural": lower + "s"}
    if random.random() < 0.78:
        names["singular"] = lower
    if random.random() < 0.72:
        names["listKind"] = kind + "List"
    nver = random.choice([1, 1, 1, 2, 2, 3])
    versions = []
    for v in range(nver):
        status_props = {"phase": {"type": "string"}}
        depth = random.random()
        if depth < 0.30:
            status_props["conditions"] = {"type": "array", "items": {"type": "object"}}
        elif depth < 0.45:
            status_props["health"] = {"type": "object", "properties": {
                "conditions": {"type": "array", "items": {"type": "object"}}}}
        elif depth < 0.55:
            status_props["health"] = {"type": "object", "properties": {
                "detail": {"type": "object", "properties": {
                    "conditions": {"type": "array", "items": {"type": "object"}}}}}}
        root = {"type": "object" if random.random() < 0.85 else "string",
                "properties": {"spec": {"type": "object",
                                        "properties": {"replicas": {"type": "integer"}}},
                               "status": {"type": "object", "properties": status_props}}}
        if random.random() < 0.18:
            root["x-kubernetes-preserve-unknown-fields"] = True
        ver = {"name": "v1alpha%d" % (v + 1) if v else "v1",
               "served": random.random() < 0.85,
               "storage": random.random() < 0.6,
               "schema": {"openAPIV3Schema": root}}
        sub = {}
        if random.random() < 0.55:
            sub["status"] = {}
        if random.random() < 0.35:
            sub["scale"] = {"specReplicasPath": ".spec.replicas", "statusReplicasPath": ".status.replicas"}
        ver["subresources"] = sub
        cols = []
        for c in COLS:
            if random.random() < 0.42:
                cols.append({"name": c, "type": "string", "jsonPath": ".status." + c.lower()})
        if cols:
            ver["additionalPrinterColumns"] = cols
        versions.append(ver)
    crd = {"apiVersion": "apiextensions.k8s.io/v1", "kind": "CustomResourceDefinition",
           "metadata": {"name": "%ss.apps.example.com" % lower},
           "spec": {"group": "apps.example.com", "names": names,
                    "scope": "Namespaced" if random.random() < 0.62 else "Cluster",
                    "versions": versions}}
    with open(os.path.join("crds", "crd_%03d.json" % i), "w") as fh:
        json.dump(crd, fh, indent=1)

