import json, os
CHECKS = ["status_subresource", "scope_namespaced", "names_defined", "schema_typed",
          "served_and_storage", "conditions_in_schema", "printer_columns_age_status"]
def has_conditions(node):
    if isinstance(node, dict):
        for k, v in node.items():
            if k == "properties" and isinstance(v, dict) and "conditions" in v:
                return True
            if has_conditions(v):
                return True
    elif isinstance(node, list):
        return any(has_conditions(x) for x in node)
    return False
def evaluate(crd):
    spec = crd.get("spec", {})
    vers = spec.get("versions", []) or []
    v0 = vers[0] if vers else {}
    names = spec.get("names", {}) or {}
    root = ((v0.get("schema") or {}).get("openAPIV3Schema") or {})
    status = (root.get("properties") or {}).get("status") or {}
    cols = v0.get("additionalPrinterColumns") or []
    colnames = {c.get("name") for c in cols if isinstance(c, dict)}
    return {
        "status_subresource": "status" in (v0.get("subresources") or {}),
        "scope_namespaced": spec.get("scope") == "Namespaced",
        "names_defined": bool(names.get("singular")) and bool(names.get("listKind")),
        "schema_typed": root.get("type") == "object" and root.get("x-kubernetes-preserve-unknown-fields") is not True,
        "served_and_storage": any(v.get("served") is True and v.get("storage") is True for v in vers),
        "conditions_in_schema": has_conditions(status),
        "printer_columns_age_status": "Age" in colnames and bool(colnames & {"Status", "Phase"}),
    }
files = sorted(f for f in os.listdir("crds") if f.endswith(".json"))
exp_files, summary, fully = {}, {c: 0 for c in CHECKS}, []
for f in files:
    res = evaluate(json.load(open(os.path.join("crds", f))))
    failed = sorted(c for c in CHECKS if not res[c])
    exp_files[f] = failed
    for c in failed:
        summary[c] += 1
    if not failed:
        fully.append(f)
total = sum(summary.values())
try:
    r = json.load(open("crd_report.json"))
except Exception:
    r = {}
got = r.get("files")
ok = isinstance(got, dict) and set(got) == set(exp_files)
if ok:
    for f, failed in exp_files.items():
        e = got.get(f) or {}
        gf = e.get("failed_checks")
        if not isinstance(e, dict) or not isinstance(gf, list) or gf != failed:
            ok = False
            break
ok = (ok and r.get("summary") == summary and r.get("total_fail_count") == total
      and r.get("fully_passing_files") == sorted(fully))
print(ok)

import json, os, re
NAME_RE = re.compile(r"^[A-Za-z0-9-]+$")
def analyse(path):
    lines = open(path, encoding="utf-8").read().split("\n")
    idx = [i for i, l in enumerate(lines) if l.strip() == "---"][:2]
    fm = lines[idx[0] + 1:idx[1]]
    block = "\n".join(fm)
    name = desc = ""
    for l in fm:
        if l.startswith("name:"):
            name = l[len("name:"):].strip()
        elif l.startswith("description:"):
            desc = l[len("description:"):].strip()
    return {"name_ok": bool(NAME_RE.match(name)),
            "desc_ok": desc.startswith("Use when"),
            "length_ok": len(block) <= 1024}
files = sorted(f for f in os.listdir("drafts") if f.endswith(".md"))
exp = {f: analyse(os.path.join("drafts", f)) for f in files}
summary = {"name_ok_count": sum(v["name_ok"] for v in exp.values()),
           "desc_ok_count": sum(v["desc_ok"] for v in exp.values()),
           "length_ok_count": sum(v["length_ok"] for v in exp.values()),
           "all_ok_count": sum(all(v.values()) for v in exp.values())}
try:
    r = json.load(open("skill_check.json"))
except Exception:
    r = {}
got = r.get("files")
ok = isinstance(got, dict) and set(got) == set(exp)
if ok:
    for f, v in exp.items():
        e = got.get(f)
        if not isinstance(e, dict) or set(e) != {"name_ok", "desc_ok", "length_ok"} or \
           any(bool(e.get(k)) != v[k] or not isinstance(e.get(k), bool) for k in v):
            ok = False
            break
ok = ok and r.get("summary") == summary
print(ok)
